// Derive the social-only scene from the website's existing illustrated assets.
// Run after changing those assets; the generated files are checked in.
import {readFile,writeFile} from 'node:fs/promises';
const base=new URL('.',import.meta.url);
const original=await readFile(new URL('../../assets/demos/quickpick-percontext-demo.html',base),'utf8');
const styles=original.match(/<style>([\s\S]*?)<\/style>/)[1].replace(/  html, body[^\n]*\n/,'').replace(/  body[^\n]*\n/,'');
await writeFile(new URL('social-scene.css',base),styles);
const setupStart=original.indexOf('  var actionIcons =');
let setup=original.slice(setupStart,original.indexOf('  /* ── Caption naming the app the menu was summoned in ── */',setupStart));
// Social demo configuration: duplicate the selected layer instead of exporting.
setup=setup.replace('  var icons =',`  actionIcons.duplicateLayer = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linejoin="round"><rect x="8" y="8" width="12" height="12" rx="1.5"/><path d="M16 8V4H4v12h4"/></svg>';
  actionIcons.pen = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"><path d="m4 20 3-12 8-4 5 5-4 8-12 3Zm0 0 7-7M15 4l5 5"/><circle cx="12" cy="12" r="1.7"/></svg>';
  var icons =`).replace('6: "exportFile"','6: "duplicateLayer"').replace('2: "layers"','2: "pen"');
setup=setup.replace('camera: FOCUS','camera: {x:380,y:395,zoom:.9},\n    appBar: {apps:["chrome","photoshop"].map(name=>({run:true,icon:icons[name].replace("<svg ","<svg class=\\"qp-app-icon\\" ")}))}');
await writeFile(new URL('social-scene-assets.js',base),'// Generated by build-guided-source.mjs; shared website artwork.\nwindow.buildSocialScene=function(){\n'+setup+'\nreturn {qp,icons,CONFIGS,winChrome,winPhotoshop};\n};\n');
let page=await readFile(new URL('social-branded.html',base),'utf8');
page=page.slice(0,page.indexOf('<script>'));
page=page.replace(/<div class="persistent-footer">[\s\S]*?<\/div>/,'');
page=page.replace('<div class="demo"><img class="front" alt="QuickPick feature demonstration"></div>','<div class="demo"><img class="front" alt="Volume and brightness demonstration"><div class="custom"><div id="qpDemo"></div></div><div class="legend"></div></div>');
const shared=['qp-core','qp-window','qp-desktop','qp-appbar','qp-thumbnail'];
page+=shared.map(n=>`<link rel="stylesheet" href="../../assets/demos/${n}.css">`).join('\n');
page+='\n<link rel="stylesheet" href="social-scene.css"><link rel="stylesheet" href="social-guided.css">\n';
page+=['qp-icons','qp-brand-icons',...shared].map(n=>`<script src="../../assets/demos/${n}.js"></script>`).join('\n');
page+='\n<script src="social-scene-assets.js"></script><script src="social-guided.js"></script></html>\n';
await writeFile(new URL('social-guided.html',base),page);
